'use strict';
const authElement=id=>document.getElementById(id);
// 登录前后沿用同一个外观选择，不依赖账本或登录状态。
const authThemeButton=authElement('authTheme');
function applyAuthTheme(value){const theme=value==='light'?'light':'dark';document.documentElement.dataset.theme=theme;authThemeButton.textContent=theme==='dark'?'☀':'☾';authThemeButton.setAttribute('aria-label',theme==='dark'?'切换浅色主题':'切换深色主题');authThemeButton.title=authThemeButton.getAttribute('aria-label');}
try{applyAuthTheme(localStorage.getItem('family-theme'));}catch{applyAuthTheme('dark');}
authThemeButton.onclick=()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';applyAuthTheme(theme);try{localStorage.setItem('family-theme',theme);}catch{}};
async function authRequest(route,data){const r=await fetch(route,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{});const value=await r.json();if(!r.ok)throw Error(value.error||'请求未完成');return value;}
let savedCode='',savedUsername='',created=false;
function showRecovery(code,username,hasSession){savedCode=code;savedUsername=username;created=hasSession;for(const id of ['loginForm','setupForm','recoverForm'])authElement(id).hidden=true;authElement('recoveryCard').hidden=false;authElement('recoveryValue').textContent=code;authElement('authTitle').textContent=hasSession?'管理员已创建':'密码已重设';authElement('authIntro').textContent='请下载保存恢复卡，以后忘记密码就不需要重新初始化账本。';authElement('continueLogin').textContent=hasSession?'进入家庭账本':'返回登录';}
async function submit(form,route,data){const b=form.querySelector('button[type="submit"]');b.disabled=true;authElement('authMessage').textContent='正在处理…';try{const r=await authRequest(route,data);authElement('authMessage').textContent='';if(r.recoveryCode)showRecovery(r.recoveryCode,data.admin?.username||data.username,!!r.user);else location.replace('/');}catch(e){authElement('authMessage').textContent=e.message;}finally{b.disabled=false;}}
authElement('loginForm').onsubmit=e=>{e.preventDefault();submit(e.currentTarget,'/api/auth/login',{username:authElement('loginUsername').value,password:authElement('loginPassword').value});};
authElement('setupForm').onsubmit=e=>{e.preventDefault();submit(e.currentTarget,'/api/auth/setup',{admin:{name:authElement('setupName').value,username:authElement('setupUsername1').value,password:authElement('setupPassword1').value,confirmPassword:authElement('setupConfirm1').value}});};
authElement('forgotButton').onclick=()=>{authElement('loginForm').hidden=true;authElement('recoverForm').hidden=false;authElement('recoverUsername').value=authElement('loginUsername').value;authElement('authTitle').textContent='重设管理员密码';authElement('authIntro').textContent='使用恢复卡找回访问权限，已保存的账目会保留。';authElement('authMessage').textContent='';};
authElement('backLogin').onclick=()=>location.replace('/login');
authElement('recoverForm').onsubmit=e=>{e.preventDefault();submit(e.currentTarget,'/api/auth/recover',{username:authElement('recoverUsername').value,code:authElement('recoverCode').value,newPassword:authElement('recoverPassword').value,confirmPassword:authElement('recoverConfirm').value});};
authElement('saveRecovery').onclick=()=>{const blob=new Blob([`家有数管理员恢复卡\n网址：${location.origin}\n登录名：${savedUsername}\n恢复码：${savedCode}\n请私下保存。每次重设或重新生成后旧码失效。\n`],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='家有数_管理员恢复卡.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
authElement('continueLogin').onclick=()=>location.replace(created?'/':'/login');
(async()=>{try{const s=await authRequest('/api/auth/status');if(s.signedIn){location.replace('/');return;}authElement('authTitle').textContent=s.setupRequired?'先创建一个管理员':'欢迎回到家有数';authElement('authIntro').textContent=s.setupRequired?'其他家庭成员稍后在设置中添加，原有账目会保留。':'登录后继续本月填报，或查看家庭资产。';authElement('setupForm').hidden=!s.setupRequired;authElement('loginForm').hidden=s.setupRequired;if(location.search.includes('changed'))authElement('authMessage').textContent='密码已修改，请重新登录。';}catch(e){authElement('authMessage').textContent=e.message;}})();
